package com.nigson.experience.content;

import java.util.*;import java.time.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;
import com.nigson.shared.problem.*;import com.nigson.shared.security.PrivateWorkload;import tools.jackson.databind.JsonNode;

@RestController
@ConditionalOnProperty(name="NIGSON_SECURITY_ENABLED",havingValue="true")
public final class CmsController {
 private final CmsService cms;public CmsController(CmsService cms){this.cms=cms;}
 private static PrivateWorkload.Proof proof(String api){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(a.getPrincipal() instanceof PrivateWorkload.Proof p)||!p.route().api().equals(api))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return p;}
 private static UUID corr(HttpServletRequest r){String v=r.getHeader("X-Correlation-ID");try{return v==null?UUID.randomUUID():UUID.fromString(v);}catch(Exception e){throw ApiValues.invalid();}}
 private static void query(HttpServletRequest r,Set<String> allowed){if(r.getQueryString()==null)return;for(var e:r.getParameterMap().entrySet())if(!allowed.contains(e.getKey())||e.getValue()==null||e.getValue().length!=1)throw ApiValues.invalid();}
 private static String header(HttpServletRequest r,String name,boolean required){var values=Collections.list(r.getHeaders(name));if(values.size()>1||required&&values.size()!=1)throw ApiValues.invalid();if(values.isEmpty())return null;String v=values.getFirst();if(v.isBlank()||v.length()>512)throw ApiValues.invalid();return v;}
 private static long version(HttpServletRequest r){String s=header(r,"If-Match",true);if(!s.matches("\"(0|[1-9][0-9]{0,18})\""))throw ApiValues.invalid();try{return Long.parseLong(s.substring(1,s.length()-1));}catch(Exception e){throw ApiValues.invalid();}}
 private static ResponseEntity<?> ok(Object v){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);}private static ResponseEntity<?> changed(Object v,int status){long ver=v instanceof CmsValues.RevisionDTO r?r.version():((CmsValues.ChannelDTO)v).version();return ResponseEntity.status(status).cacheControl(CacheControl.noStore()).eTag("\""+ver+"\"").body(v);}
 @GetMapping(value="/api/v1/content/{type}/{slug}",produces="application/json") public ResponseEntity<?> get(HttpServletRequest r,@PathVariable String type,@PathVariable String slug,@RequestParam(defaultValue="en")String locale,@RequestParam(required=false)String market){query(r,Set.of("locale","market"));if(r.getContentLengthLong()>0)throw ApiValues.invalid();var v=cms.get(type,slug,locale,market);if(v==null)throw new Problem.Failure(ProblemCode.NOT_FOUND);return ok(v);}
 @GetMapping(value="/api/v1/content",produces="application/json") public ResponseEntity<?> list(HttpServletRequest r,@RequestParam String type,@RequestParam(defaultValue="en")String locale,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="publishedAt,desc")String sort){query(r,Set.of("type","locale","page","size","sort"));return ok(cms.page(type,locale,page,size,sort));}
 @GetMapping(value="/api/v1/staff/content-revisions/{id}/preview",produces="application/json") public ResponseEntity<?> preview(HttpServletRequest r,@PathVariable String id){query(r,Set.of());if(r.getContentLengthLong()>0)throw ApiValues.invalid();return ok(cms.preview(proof("API-083"),ApiValues.uuid(id)));}
 @PostMapping(value="/api/v1/staff/content",consumes="application/json",produces="application/json") public ResponseEntity<?> create(HttpServletRequest r,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.create(proof("API-078"),b,header(r,"Idempotency-Key",true),corr(r)),201);}
 @PostMapping(value="/api/v1/staff/content/{id}/revisions",consumes="application/json",produces="application/json") public ResponseEntity<?> revise(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.addRevision(proof("API-079"),ApiValues.uuid(id),version(r),b,header(r,"Idempotency-Key",true),corr(r)),201);}
 @PostMapping(value="/api/v1/staff/content-revisions/{id}/review",consumes="application/json",produces="application/json") public ResponseEntity<?> review(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.review(proof("API-080"),ApiValues.uuid(id),version(r),b,header(r,"Idempotency-Key",true),corr(r)),200);}
 @PostMapping(value="/api/v1/staff/content-revisions/{id}/approval",consumes="application/json",produces="application/json") public ResponseEntity<?> approval(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.approval(proof("API-081"),ApiValues.uuid(id),version(r),b,header(r,"Idempotency-Key",true),corr(r)),200);}
 @PostMapping(value="/api/v1/staff/content-revisions/{id}/publication",consumes="application/json",produces="application/json") public ResponseEntity<?> publication(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.publication(proof("API-082"),ApiValues.uuid(id),version(r),b,header(r,"Idempotency-Key",true),corr(r)),200);}
 @PutMapping(value="/api/v1/staff/channel-configurations/{id}",consumes="application/json",produces="application/json") public ResponseEntity<?> channel(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){query(r,Set.of());return changed(cms.updateChannel(proof("API-086"),ApiValues.uuid(id),version(r),b,header(r,"Idempotency-Key",true),corr(r)),200);}
 @GetMapping(value="/api/v1/seo/sitemap",produces="application/json") public ResponseEntity<?> sitemap(HttpServletRequest r){query(r,Set.of());return ok(Map.of("entries",cms.sitemap()));}
 @GetMapping(value="/api/v1/channels",produces="application/json") public ResponseEntity<?> channels(HttpServletRequest r){query(r,Set.of());return ok(Map.of("whatsapp",cms.channels().stream().filter(x->x.kind().equals("WHATSAPP")).map(CmsValues.ChannelDTO::publicValue).toList(),"social",cms.channels().stream().filter(x->x.kind().equals("SOCIAL")).map(CmsValues.ChannelDTO::publicValue).toList(),"maps",cms.channels().stream().filter(x->x.kind().equals("MAP")).map(CmsValues.ChannelDTO::publicValue).toList()));}
}
